ALTER TABLE BZA_BOOTSTRAP_APPROVAL ADD (
    CLAIM_OWNER_ID VARCHAR2(100 CHAR),
    CLAIM_EXPIRES_AT TIMESTAMP,
    CLEANUP_STATUS VARCHAR2(20 CHAR) DEFAULT 'PENDING' NOT NULL,
    CLEANUP_FAILURE_CODE VARCHAR2(100 CHAR),
    CLEANUP_UPDATED_AT TIMESTAMP
);

ALTER TABLE BZA_BOOTSTRAP_APPROVAL
    ADD CONSTRAINT CK_BZA_BOOTSTRAP_CLEANUP_STATUS
    CHECK (CLEANUP_STATUS IN ('PENDING','COMPLETED','FAILED'));

CREATE INDEX IX_BZA_BOOTSTRAP_CLAIM_LEASE
    ON BZA_BOOTSTRAP_APPROVAL(STATUS, CLAIM_EXPIRES_AT);
